{"code": "import random

def simulate(n):
    count = 0
    for _ in range(n):
        x = random.uniform(0, 3)
        y = random.uniform(0, 3)
        if (1 + x > y) and (1 + y > x) and (x + y > 1):
            count += 1
    return count / n

print(simulate(1000000))"}

